primaryQuery:
run: order_items -> {
  aggregate:
    shipped_items is count() { where: shipped_at is not null }
    total_items is count()
} -> {
  select:
    shipped_items
    total_items
    shipped_share is round(shipped_items / total_items, 6)
}

verifyQuery:
run: order_items -> {
  aggregate:
    total_items is count()
    shipped_items is count() - count() { where: shipped_at is null }
} -> {
  select: shipped_items, total_items, shipped_share is round(shipped_items / total_items, 6)
}
